#!/usr/bin/env python3
"""Deploy-gate evaluator.

Reads checks.json (gate rules) and metrics.json (actual values),
evaluates every rule, prints a verdict table and a final ALLOW/BLOCK.

Exit codes: 0 = ALLOW, 1 = BLOCK (including config/metric errors).
"""

import argparse
import json
import sys

# rule name -> (metric key it consumes, description of the threshold)
KNOWN_RULES = {
    "min_coverage": ("coverage", "coverage must be >= threshold"),
    "max_failed_tests": ("failed_tests", "failed tests must be <= threshold"),
    "max_critical_vulns": ("critical_vulns", "critical vulns must be <= threshold"),
    "required_approvals": ("approvals", "approvals must be >= threshold"),
}

LOWER_IS_BETTER = {"max_failed_tests", "max_critical_vulns"}


def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def evaluate(checks, metrics):
    """Evaluate every rule. Returns list of verdict dicts."""
    # Validate all rule names first: reject unknown rules outright.
    unknown = [name for name in checks if name not in KNOWN_RULES]
    if unknown:
        raise KeyError(unknown[0])

    results = []
    for name in KNOWN_RULES:
        if name not in checks:
            continue
        threshold = checks[name]
        metric_key = KNOWN_RULES[name][0]

        if metric_key not in metrics or metrics[metric_key] is None:
            results.append({
                "rule": name,
                "threshold": threshold,
                "actual": None,
                "pass": False,
                "reason": "metric missing",
            })
            continue

        actual = metrics[metric_key]
        if name in LOWER_IS_BETTER:
            ok = actual <= threshold
        else:
            ok = actual >= threshold
        results.append({
            "rule": name,
            "threshold": threshold,
            "actual": actual,
            "pass": ok,
            "reason": "" if ok else KNOWN_RULES[name][1],
        })
    return results


def render_table(results):
    lines = []
    header = f"{'RULE':<22} {'THRESHOLD':>10} {'ACTUAL':>10} {'VERDICT':>8}  REASON"
    lines.append(header)
    lines.append("-" * len(header))
    for r in results:
        actual = "-" if r["actual"] is None else str(r["actual"])
        verdict = "PASS" if r["pass"] else "FAIL"
        lines.append(
            f"{r['rule']:<22} {str(r['threshold']):>10} {actual:>10} {verdict:>8}  {r['reason']}"
        )
    return "\n".join(lines)


def main(argv=None):
    parser = argparse.ArgumentParser(description="Deploy-gate evaluator")
    parser.add_argument("--checks", default="checks.json")
    parser.add_argument("--metrics", default="metrics.json")
    args = parser.parse_args(argv)

    try:
        checks = load_json(args.checks)
    except (OSError, ValueError) as exc:
        print(f"ERROR: cannot read checks file {args.checks}: {exc}", file=sys.stderr)
        return 1
    try:
        metrics = load_json(args.metrics) or {}
    except (OSError, ValueError) as exc:
        print(f"ERROR: cannot read metrics file {args.metrics}: {exc}", file=sys.stderr)
        return 1

    try:
        results = evaluate(checks, metrics)
    except KeyError as exc:
        print(f"ERROR: unknown rule in checks.json: {exc.args[0]}", file=sys.stderr)
        return 1

    print(render_table(results))
    blocked = any(not r["pass"] for r in results)
    print("\nFINAL VERDICT: " + ("BLOCK" if blocked else "ALLOW"))
    return 1 if blocked else 0


if __name__ == "__main__":
    sys.exit(main())

